INSERT INTO `analysis_summaries` (`document_id`, `executive_summary`, `compliance_score`, `total_risks`, `high_risk_count`, `medium_risk_count`, `low_risk_count`) VALUES
('doc-1', 'Commercial IT services agreement between Acme Corp and CloudFlow Systems spanning a 36-month service term. While the agreement establishes clear operational deliverables and baseline performance SLAs, it introduces significant legal and financial exposure through an uncapped indemnification clause for third-party IP claims, asymmetric unilateral termination rights for convenience favoring the vendor, and non-standard governing law provisions in Delaware with waiver of jury trial rights.', 68, 4, 2, 1, 1),
('doc-2', 'SLA and Data Processing Addendum governing enterprise SaaS workloads. Establishes a 99.95% monthly uptime service level with tiered service credits. Data handling largely conforms with standard GDPR/CCPA security baselines, though notification intervals for confirmed personal data security breaches are defined as "within reasonable commercial timing" rather than statutory 72-hour standards.', 82, 3, 0, 2, 1),
('doc-3', 'Standard bilateral non-disclosure agreement for preliminary commercial partnerships. Confidentiality covenants are well-balanced with customary exclusions for independently developed or publicly available information. Term is bounded to three (3) years from disclosure with mutual return or destruction covenants.', 94, 1, 0, 0, 1),
('doc-4', 'Perpetual enterprise software license agreement with annual maintenance addenda. Contains highly aggressive software audit rights allowing vendor unannounced remote telemetry inspection, aggressive automated annual price escalations tied to list price rather than inflation indices, and restrictive reverse-engineering prohibitions impacting backup and security testing.', 55, 5, 3, 2, 0),
('doc-5', 'Commercial office space lease covering 15,000 RSF. Contains triple-net (NNN) operating cost pass-throughs with uncapped common area maintenance (CAM) expense escalations and broad landlord indemnifications regarding facility interruptions.', 78, 3, 1, 1, 1),
('doc-6', 'Deliverable-based Statement of Work for enterprise cloud infrastructure modernization. Features clear milestone acceptance criteria, defined warranty periods of 90 days, and equitable change-order dispute resolution mechanisms.', 91, 1, 0, 0, 1)
INSERT INTO `risk_findings` (`id`, `document_id`, `title`, `severity`, `category`, `clause_reference`, `explanation`, `evidence_snippet`, `recommendation`, `page_number`) VALUES
('find-1-1', 'doc-1', 'Uncapped Third-Party Intellectual Property Indemnification', 'high', 'Legal Liability', 'Section 14.3 (Indemnification Obligations)', 'The customer is obligated to defend, indemnify, and hold harmless the vendor against all claims, damages, and legal expenses arising from third-party IP infringement without an aggregate monetary liability cap or carve-out for vendor-modified components.', 'Customer shall defend, indemnify, and hold harmless Provider, its affiliates, and their respective directors, officers, and employees from and against any and all claims, demands, losses, liabilities, and expenses (including attorneys fees) arising out of or resulting from any third-party claim alleging that Customer Data or Customers use of the Services infringes or misappropriates any intellectual property right, without limitation as to aggregate damages.', 'Insert a reciprocal liability cap equal to twelve (12) months of aggregate fees paid under this Agreement, and exclude claims arising from Provider unauthorized modifications.', 8),
('find-1-2', 'doc-1', 'Unilateral Termination for Convenience with 15-Day Notice', 'high', 'Commercial Risk', 'Section 18.2 (Early Termination Rights)', 'Provider retains the unilateral discretion to terminate the agreement for convenience on fifteen (15) days notice, while Customer has no reciprocal early exit right and must forfeit all prepaid non-refundable implementation retainers.', 'Provider may terminate this Agreement or any applicable Order Form in whole or in part at its sole discretion for convenience upon fifteen (15) calendar days prior written notice to Customer. In the event of such termination, Customer shall not be entitled to refund of any pre-paid implementation fees.', 'Require minimum ninety (90) days advance notice for convenience termination, grant mutual exit rights to Customer, and mandate pro-rata refund of prepaid unamortized fees.', 11),
('find-1-3', 'doc-1', 'Foreign Governing Law & Jury Trial Waiver', 'medium', 'Compliance', 'Section 22.8 (Governing Law and Dispute Resolution)', 'Mandates arbitration and choice of law under the State of Delaware, while enforcing an absolute waiver of jury trial rights and class action participation, shifting forum costs disproportionately to customer.', 'This Agreement and any dispute arising hereunder shall be governed by the laws of the State of Delaware, without regard to conflict of law doctrines. Each party hereby irrevocably waives any and all rights to trial by jury in any legal proceeding arising out of or related to this Agreement.', 'Propose neutral governing law jurisdiction (e.g., State of New York or mutual home state) and strike mandatory class action waivers.', 14),
('find-1-4', 'doc-1', 'Ambiguous Service Level Agreement (SLA) Penalty Calculation', 'low', 'Financial', 'Schedule B (Service Level Commitments, Clause 4.1)', 'Penalty credits for monthly downtime below 99.5% require customer submission within five days and are capped at 5% of monthly fees, creating weak financial incentives for high availability.', 'In the event monthly uptime falls below 99.5%, Customer shall be eligible to request a Service Credit equal to 5% of the applicable monthly recurring fee, provided Customer submits formal written verification within five (5) business days of month-end.', 'Increase tiered credits up to 25% for severe downtime and extend the claim filing window from 5 to 30 days.', 19)
